-- Сигналы ошибок у type_word («Напечатай слово»): слот = номер буквы слова, подсказка на
-- ПЕРВУЮ неверную букву напечатанного. Правило для легенды обменного JSON: когда ставить
-- signals у этого типа и как писать ноду-сигнал. Таблиц и колонок не меняем. Идемпотентно:
-- вставка только если такого правила ещё нет.
insert into public.lesson_rules (rule_text, sort_order, category)
select
  'type_word тоже умеет signals — персональную подсказку на конкретную БУКВУ слова (слот — номер буквы с нуля, пробелы не считаются; «tries»: 0=t, 1=r, 2=i, 3=e, 4=s). Сигнал срабатывает на ПЕРВУЮ неверную букву напечатанного слова («Trys» → слот 2), один раз за урок на каждую ноду-сигнал: попытка не тратится, панель не закрывается, неверная буква мигает, пока ученик её не сотрёт. Слово короче верного («Tr») или с лишними буквами в конце сигнала не вызывает — это обычная ошибка (responseWrong, попытка тратится). Ставь signals только на букву, где типичная ошибка имеет ПОНЯТНУЮ причину (y вместо i в «tries» — правило y → i; одна s вместо двух в «passes»), 1–2 сигнала на ноду, а не на каждую букву. Нода-сигнал — короткая текстовая нода (1–2 фразы) с намёком на причину, а не готовым ответом: не пиши слово целиком и не печатай верное написание за ученика. Размещение, самодостаточность текста и запрет дословного повтора — те же правила, что у signals таблицы и phrase_assembly.',
  240,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'type_word тоже умеет signals — персональную подсказку на конкретную БУКВУ слова%'
);
